      "Тезис 2: радикальная идеология — уничтожение городов, отмена денег, ликвидация интеллигенции, религии и даже семейных связей ради 'чистого' крестьянского общества",
      "Тезис 3: механизмы репрессий — 'поля смерти', пыточная тюрьма S-21 (Туол Сленг), принудительный труд, голод и массовые казни",
      "Тезис 4: внешний контекст — влияние холодной войны, конфликт с Вьетнамом, молчаливая поддержка Китая и равнодушие мирового сообщества",
